config.code:
import json

try:
    raw_summary = inputs.get('raw_summary', {})

    # 防御性解析1：如果大模型把 JSON 当成字符串传过来了，尝试反序列化
    if isinstance(raw_summary, str):
        try:
            raw_summary = json.loads(raw_summary)
        except json.JSONDecodeError:
            pass # 交给后面的类型检查报错

    # 防御性解析2：提取数组并做类型校验
    results = raw_summary.get('assertion_results', []) if isinstance(raw_summary, dict) else []
    if not isinstance(results, list):
        raise ValueError("大模型未按要求返回 assertion_results 数组格式")

    # 正常计算逻辑
    total = len(results)
    if total == 0:
        raise ValueError("断言数组为空，大模型可能忽略了验证步骤")

    passed = sum(1 for r in results if r.get('passed') is True)
    failed = total - passed
    pass_rate = round(passed / total, 2)

    grading_data = {
        'assertion_results': results,
        'summary': {
            'passed': passed,
            'failed': failed,
            'total': total,
            'pass_rate': pass_rate
        }
    }

    outputs['eval_result'] = {
        'pass': failed == 0,
        'reason': '通过所有断言' if failed == 0 else f'有 {failed} 条断言未通过',
        'grading_data': grading_data
    }

except Exception as e:
    # 🚨 终极兜底逻辑：大模型发狂、格式损毁、未执行验证等情况全部走这里
    fallback_grading = {
        'assertion_results': [],
        'summary': {
            'passed': 0,
            'failed': 1,
            'total': 1,
            'pass_rate': 0.0
        }
    }
    outputs['eval_result'] = {
        'pass': False,
        'reason': f'裁判系统解析失败 (大模型幻觉或格式化错误): {str(e)}',
        'grading_data': fallback_grading
    }
